    def connect(self, **kwargs):
        client_connect_retry_timeout = kwargs.get(
            'client_connect_retry_timeout') or 60
        start_server_retry_timeout = kwargs.get(
            'start_server_retry_timeout') or 60
        logger.info("client connect retry timeout is:{}".format(
            client_connect_retry_timeout))
        logger.info("start server retry timeout is:{}".format(
            start_server_retry_timeout))
        try:
            self._create_trex_server_config_file(**kwargs)
            self._start_trex_server(**kwargs)
            self.client = api.STLClient(
                server=kwargs['server_ip'], verbose_level='error')
            self.client.set_timeout(3600)
            for retry in range(int(client_connect_retry_timeout / 5)):
                try:
                    self.client.connect()
                    logger.info("Connection successful")
                    break
                except Exception as connect_error:
                    logger.warn('''Connection to server failed and retrying {}th
                     time due to:{}'''.format(retry, connect_error))
                    time.sleep(5)
            else:
                BuiltIn().fail("Failed to connect to Trex Server ...")
            # Initialisation port
            self._initialise_ports()
            self.IS_CONNECTED = True
            logger.info("Successfully Connected to Trex server...")
            return 1

        except Exception as connect_error:
            logger.error(
                "Connection to Trex Server failed due to Trex Error {}".format(connect_error))

    def _initialise_ports(self):
        self.client.reset(ports=list(self.port_name_to_id_map.values()))
        self.client.set_port_attr(
            list(self.port_name_to_id_map.values()), True)
        # move to service mode
        self.client.set_service_mode(
            list(self.port_name_to_id_map.values()), enabled=True)
        # remove all old name spaces from all the ports
        self.client.namespace_remove_all(
            list(self.port_name_to_id_map.values()))

    def _create_trex_server_config_file(self, **kwargs):

        if kwargs.get('trex_cfg_yaml') is None:
            path = os.path.abspath(__file__)
            dir_path = os.path.dirname(path)
            templateLoader = jinja2.FileSystemLoader(searchpath=dir_path)
            templateEnv = jinja2.Environment(loader=templateLoader)
            TEMPLATE_FILE = "trex_cfg_template.yaml"
            template = templateEnv.get_template(TEMPLATE_FILE)
            interface_value_list = kwargs.get('interface_list')
            host_ip_cmd = "sudo hostname -I | awk '{print $1}'"
            logger.info("Fetching host ip address")
            logger.info("Host ip address command is : {}".format(host_ip_cmd))
            host_ip, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=kwargs.get('server_ip'),
                username=kwargs.get('server_username'),
                password=kwargs.get('server_password'), command=host_ip_cmd,
            )
            logger.info(
                "Host IP address is : {} status is : {}".format(host_ip, status))
            default_gateway_ip_cmd = "sudo ip route list | awk ' /^default/ {print $3}'"
            logger.info("Fetching default gateway ip address")
            logger.info("Default gateway ip address command is : {}".format(
                default_gateway_ip_cmd))
            gateway, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=kwargs.get('server_ip'),
                username=kwargs.get('server_username'),
                password=kwargs.get('server_password'), command=default_gateway_ip_cmd,
            )
            logger.info(
                "Gateway IP address is : {} status is : {}".format(gateway, status))
            for interface in interface_value_list:
                if interface != "dummy":
                    self.port_name_to_id_map[interface] = interface_value_list.index(
                        interface)
            logger.info("### Port name to id map : {}".format(
                self.port_name_to_id_map))
            interface_value_list = [encode_str(intf) for intf in interface_value_list]
            logger.info("interface_value_list is {}".format(
                interface_value_list))
            server_config_file_content = template.render(
                interface_value_list=interface_value_list, num_ports=len(interface_value_list), ip=host_ip, gateway=gateway)
            logger.info("Rendered content is {}".format(
                server_config_file_content))
            logger.info("Log dir is {}".format(
                BuiltIn().get_variable_value("${TEST_LOG_DIR}")))
            # dest_file = os.path.join(BuiltIn().get_variable_value(
            #    "${TEST_LOG_DIR}"), 'trex_cfg.yaml')
            trex_cfg_yaml = os.path.join('/tmp', 'trex_cfg.yaml')
            with open(trex_cfg_yaml, 'w') as f:
                f.write(server_config_file_content)
        else:
            trex_cfg_yaml = kwargs.get('trex_cfg_yaml')
        logger.info("Trex cfg yaml is  {}".format(trex_cfg_yaml))

        logger.info(
            "Trex config file created succesfully {}".format(trex_cfg_yaml))

        if os.path.exists(trex_cfg_yaml):
            if kwargs.get('server_ip') != "127.0.0.1":
                status = Communicator.get_instance().copy_file_to_linux(
                    ip=kwargs.get('server_ip'),
                    username=kwargs.get('server_username'),
                    password=kwargs.get('server_password'),
                    local_path=trex_cfg_yaml, remote_file='/etc/trex_cfg.yaml'
                )
            else:
                import subprocess
                copy_command = "sudo cp {} /etc/trex_cfg.yaml".format(
                    trex_cfg_yaml)
                out = (subprocess.Popen(
                    copy_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True))
                output, status = out.communicate()
                status = out.returncode
                if status:
                    raise Exception('''Failed to copy the trex
                 server config file to trex server {}....'''.format(
                        kwargs.get('server_ip')))

    def _execute_start(self, ip, username, password, command_list):
        try:
            ssh_client = paramiko.SSHClient()
            ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh_client.get_host_keys().clear()
            ssh_client.set_missing_host_key_policy(
                paramiko.AutoAddPolicy())
            ssh_client.connect(ip, port=22, username=username,
                               password=password, banner_timeout=60)
            for command in command_list:
                stdin, stdout, stderr = ssh_client.exec_command(
                    command, timeout=60)
            return (0, None)
        except Exception as e:
            logger.warn("Starting server failed due to {}".format(e))
            return (1, str(e))

    def _start_trex_server(self, **kwargs):
        # get the status of trex server, if already running kill the process
        # get_tcp_port_usage_command = "netstat -antlep |
        # {tcl_server_port}".format(tcl_server_port=
        # self.traffic_gen_details.get('tcl_server_port'))
        for retry in range(int(kwargs.get('start_server_retry_timeout', 60) / 5)):
            get_tcp_port_usage_command_template = "sudo netstat -antlep | grep %(server_port)s"
            get_tcp_port_usage_command = get_tcp_port_usage_command_template % dict(
                server_port=kwargs.get('server_port'))
            logger.info("**********netsta command")
            logger.info(get_tcp_port_usage_command)

            output, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=kwargs.get('server_ip'),
                username=kwargs.get('server_username'),
                password=kwargs.get('server_password'),
                command=get_tcp_port_usage_command)
            logger.info("output is ::")
            logger.info(output)
            logger.info(status)
            if output:
                logger.info("***************Inside the if condition")
                logger.info(output)
                output = list((re.sub(r'\s+', ' ', output).strip()).split(" "))
                pid = output[8].split('/')[0].strip()
                kill_cmd = "sudo kill -9 {pid}".format(pid=pid)
                logger.info("Killing the process")
                logger.info(kill_cmd)
                status, output = Communicator.get_instance().execute_command_remotely_and_verify(
                    ip=kwargs.get('server_ip'),
                    username=kwargs.get('server_username'),
                    password=kwargs.get('server_password'), command=kill_cmd,
                )
                logger.info(status)
            # start the trex server
            start_server_cmd_template = "cd {};sudo ./t-rex-64 -i --software --no-scapy-server".format(
                kwargs.get('server_bin_path'))
            # start_server_cmd=start_server_cmd_template % dict(
            # server_path=self.traffic_gen_details.get(
            # 'traffic_gen_hlt_srv_location'))
            logger.info(start_server_cmd_template)
            status, output = self._execute_start(
                ip=kwargs.get('server_ip'),
                username=kwargs.get('server_username'),
                password=kwargs.get('server_password'),
                command_list=[start_server_cmd_template])

            # Add retry to check if server has started
            # Check netstat to be LISTEN
            logger.info("start status:{}".format(status))
            logger.info("Output::".format(output))
            if self._wait_for_server_started(**kwargs) == 1:
                logger.info("server start successful")
                break
            else:
                logger.warn(
                    "Connection to server failed and retrying {}th time".format(retry))
                time.sleep(5)
        else:
            BuiltIn().fail("Failed to start Trex Server ...")

    def _wait_for_server_started(self, **kwargs):
        tcp_port_netstat_template = "sudo netstat -antlep | grep %(server_port)s"
        tcp_port_netstat = tcp_port_netstat_template % dict(
            server_port=kwargs.get('server_port'))
        logger.info("Netstat command is --{}--".format(tcp_port_netstat))
        for i in range(12):
            output, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=kwargs.get('server_ip'),
                username=kwargs.get('server_username'),
                password=kwargs.get('server_password'),
                command=tcp_port_netstat, pty=True)
            logger.info("output is ::")
            logger.info(output)
            logger.info(status)
            if output:
                output = list((re.sub(r'\s+', ' ', output).strip()).split(" "))
                if re.search('LISTEN', output[5]) is not None:
                    logger.info("Server has started listening ...")
                    return 1
                else:
                    logger.warn("Waiting for server to move to LISTEN state")
            time.sleep(5)
        else:
            return 0

    def _generate_profile_from_xls(self, **kwargs):
        if not all(arg in kwargs for arg in ['config_file']):
            raise Exception("Argument config_file missing")
        # import sys
        # sys.path.append('/root/chris_trex/')
        # print(sys.path)
        from JumpStream.lib.input_parser.parser import Parser
        from JumpStream.lib.traffic_generator.traffic_generator import TrafficGen
        # import jumpstream_api
        # init needed class
        logger.debug("Loading config file {} and replcaing the following attributes {}".format(
            kwargs['config_file'], kwargs.get('stream_modify_details')))
        parser = Parser().get_instance(
            input=kwargs['config_file'], traffic_generator='trex',
            variable_definition_dict=kwargs.get('stream_modify_details'))
        traffic_gen = TrafficGen().get_instance(traffic_generator='trex',
                                                server_info=parser.get_variables_mapping())
        # set mapping for traffic generator
        traffic_gen.init_mapping(stream_field_mapping=parser.get_mapping_dict(),
                                 stream_header_mapping=parser.get_stream_header_mapping())

        # reserve ports
        traffic_gen.reserve_ports(port_list=parser.get_port_list())

        # create streams
        stream_profiles = traffic_gen.add_stream(
            stream_dict=parser.get_stream_dict(), template_dict=parser.get_template_dict())

        # create interfaces
        ns_profiles = traffic_gen.add_connected_interface(
            interfaces=parser.get_connected_interface_dict())
        traffic_gen.add_unconnected_interface(
            interfaces=parser.get_unconnected_interface_dict())
        self.unconnected_interface_map = parser.get_unconnected_interface_dict()
        logger.info("DEBUG............unconnected_interface_map:{}".format(
            self.unconnected_interface_map))
        self.interface_map = parser.get_connected_interface_dict()

        self.port_map = traffic_gen.port_dict
        # save
        traffic_gen.save_config('/tmp/trex_auto_gen.py')
        return list(itertools.chain(stream_profiles, [ns_profiles]))

