    def _create_interface_namespace_map(self):
        port_list = []
        for interface in list(self.interface_map.keys()):
            port_list.append(
                self.port_map[self.interface_map[interface]['VportName']])
        unique_port_list = list(dict.fromkeys(port_list))

        for port in unique_port_list:
            node_name = self.client.set_namespace(port, method='get_nodes')
            node_name_info_list = self.client.set_namespace(port, method='get_nodes_info',
                                                            macs_list=node_name['result']['nodes'])
            logger.info("debug.......node_name_info_list::{}".format(
                node_name_info_list))
        for interface in list(self.interface_map.keys()):
            for node in node_name_info_list['result']['nodes']:
                if self.interface_map[interface].get('ipv4') and node['ipv4'].get('src'):
                    if self.interface_map[interface]['ipv4'].get('IPv4address') == node['ipv4'].get('src') and \
                            self.interface_map[interface]['ipv4'].get('IPv4Gateway') == node['ipv4'].get('dst'):
                        self.interface_namespace_map[interface] = node
                        logger.info("debug......node_name::{}".format(node))
                        logger.info("debug......interface_namespace_map:{}".format(
                            self.interface_namespace_map))
                        break

    def _unconnected_interface(self):
        logger.info("DEBUG.................unconnected INTERFACE_MAP ::{}".format(
            self.unconnected_interface_map))
        for interface in list(self.unconnected_interface_map.keys()):
            logger.info("debug......interface_namespace_map::{}".format(
                self.interface_namespace_map))
            if self.unconnected_interface_map[interface].get('ipv4'):
                unconnected_interface_ip = self.unconnected_interface_map[interface].get(
                    'ipv4')['UI_IPv4address']
                unconnected_interface_subnet = self.unconnected_interface_map[
                    interface].get('ipv4')['UI_IPv4Subnet']
                trex_ns = self.interface_namespace_map[self.unconnected_interface_map[
                    interface]['unconnected']['UI_ConnectedVia']]['linux-ns']
                unconnected_interface_incremented_ip = ipaddress.ip_address(
                    unconnected_interface_ip) + int(1)
            list_namespace = "sudo ip netns list"
            list_namespace_output, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=self.traffic_gen_details.get('tcl_server_ip'),
                username=self.traffic_gen_details.get('tcl_username'),
                password=self.traffic_gen_details.get('tcl_password'), command=list_namespace,
                private_key=self.traffic_gen_details.get('tcl_private_key'))
            logger.info("output:{}, status:{} is:".format(
                list_namespace_output, status))
            interface_name_modified = '{}{}'.format(
                interface[0:9], random.randint(1, 100)).replace(' ', '_')
            if 'ns_{interface}'.format(interface=interface_name_modified) in list_namespace_output:
                add_namespace_command = "sudo ip netns delete ns_{interface} && ".format(
                    interface=interface_name_modified)
            else:
                add_namespace_command = ""
            add_namespace_command = add_namespace_command + """sudo ip netns add ns_{interface} &&
             sudo ip link add U_{interface} type veth peer name T_{interface} &&
              sudo ip link set U_{interface} netns ns_{interface} &&
               sudo ip link set T_{interface} netns {trex_ns} &&
                sudo ip netns exec ns_{interface} ip link set dev U_{interface} mtu 9280 up &&
                 sudo ip netns exec {trex_ns} ip link set dev T_{interface} mtu 9280 up &&
                  sudo ip netns exec ns_{interface} ifconfig U_{interface} {ip}/{subnet} &&
                   sudo ip netns exec {trex_ns} ifconfig T_{interface} {new_ip}/{subnet}""".format(interface=interface_name_modified, ip=unconnected_interface_ip, trex_ns=trex_ns, subnet=unconnected_interface_subnet, new_ip=unconnected_interface_incremented_ip)
            # print(add_namespace_command)
            logger.info("DEBUG.................add_namespace_command ::{}".format(
                add_namespace_command))

            output, status = Communicator.get_instance().execute_command_remotely_and_verify(
                ip=self.traffic_gen_details.get('tcl_server_ip'),
                username=self.traffic_gen_details.get('tcl_username'),
                password=self.traffic_gen_details.get('tcl_password'),
                command=add_namespace_command, private_key=self.traffic_gen_details.get('tcl_private_key'))
            logger.info("output:{}, status:{} is:".format(output, status))
            logger.info(status)
            if status == 0:
                logger.info("Unconnected interface added successfully")
            else:
                BuiltIn().fail("Failed to add unconnected interface")

