    def _get_port_for_stream(self, stream_handle=None):
        """

        Fetches stream object from name

        Args:
            stream_regexp: name of the stream

        Returns: stream object list

        Raises: IxiaError when fetch fails

        """
        if stream_handle:
            for port, stream_dict in list(self.port_stream_map.items()):
                if stream_handle.name in list(stream_dict.keys()):
                    return port
        else:
            return list(self.port_stream_map.keys())

    def start_traffic(self, streams_list=None, traffic_pm=None, duration=None):
        """

        Args:
            streams_list:
            traffic_pm:
            duration:

        Returns:

        """
        if streams_list:
            stream_handle = list(itertools.chain.from_iterable(
                [self._get_stream_object(stream) for stream in re.split(r'\s+',
                                                                        streams_list.strip())]))
        else:
            stream_handle = self._get_stream_object()
        logger.info("Stream handles are {}".format(stream_handle))
        ports = set()
        profile_id_list = []
        for stream in stream_handle:
            logger.info("stream pg id is {}".format(stream.get_pg_id()))
            try:
                port = self._get_port_for_stream(stream)
                ports.add(port)
                profile_id = "{}.{}".format(port, stream.name)
                logger.info('''Adding stream ... pgid = {} name = {} port = {}
                 profile_id = {}'''.format(stream.get_pg_id(),
                                           stream.name, port, profile_id))
                profile_id_list.append(profile_id)
                stream_id = stream.get_id()
                try:
                    logger.info("Removing profile {} , stream_id {} before adding {}".format(
                        profile_id, stream.get_pg_id(), stream.name))
                    self.client.remove_all_streams(ports=profile_id)
                except Exception as remove_error:
                    logger.warn(
                        "Removing failed due to {}".format(remove_error))

                # try:
                #     logger.info("Removing profile {} , stream_id {} before adding {}".format(
                #         profile_id, stream.get_pg_id(), stream.name))
                #     self.client.remove_streams(
                #         stream.get_pg_id(), ports=profile_id)
                # except Exception as remove_error:
                #     logger.warn(
                #         "Removing failed due to {}".format(remove_error))
                self.client.add_streams(stream, ports=profile_id)
                self.current_streams_added.append(stream)
            except Exception as e:
                BuiltIn().fail("Start failed with the following exception {}".format(e))
        if not duration:
            duration = -1
        logger.info("Starting traffic profile {}".format(profile_id_list))
        try:
            self.client.start(ports=profile_id_list,
                              duration=int(duration), force=True)
        except Exception as start_error:
            if re.findall(r'error:\s+instruction id.*fix hw command', str(start_error)):
                logger.info(
                    "Fix checksum has failed !! Hence Removing it for the respective streams")
                ret_handles = Trex._remove_fix_checksum_from_stream(
                    stream_handle)
                profile_id_list = self.remove_and_add_streams(ret_handles)
                try:
                    self.client.start(ports=profile_id_list,
                                      duration=int(duration), force=True)
                except Exception as start_error_after_chksum:
                    BuiltIn().fail("Traffic Start failed with  exception {} even after removing checksum!!".format(
                        start_error_after_chksum))
            else:
                BuiltIn().fail("Traffic Start failed with  exception {} ".format(start_error))

        # time.sleep(3)
        logger.info("Traffic Started successfully!!!")

    @staticmethod
    def _remove_fix_checksum_from_stream(stream_handle):
        ret_handles = []
        for stream in stream_handle:
            vm_instrutcions_tmp = []
            for instruction in stream.fields['vm']['instructions']:
                if not (instruction.get("type") == 'fix_checksum_hw'):
                    vm_instrutcions_tmp.append(instruction)
            logger.info(
                "Newly created instructions set by removing checksum is {} for stream {}".format(vm_instrutcions_tmp,
                                                                                                 stream.name))
            stream.fields['vm'] = {'instructions': vm_instrutcions_tmp}
            ret_handles.append(stream)
        return ret_handles

