    def _get_stream_object(self, stream_regexp=None):
        """

        Fetches stream object from name

        Args:
            stream_regexp: name of the stream

        Returns: stream object list

        Raises: IxiaError when fetch fails

        """
        if stream_regexp is None:
            all_stream = list()
            for port, stream_dict in list(self.port_stream_map.items()):
                for stream_name, stream_obj in list(stream_dict.items()):
                    all_stream.append(stream_obj)
            return all_stream

        elif '*' in stream_regexp:
            stream_regexp = stream_regexp
        else:
            stream_regexp = '^' + stream_regexp + '$'
        r_obj = re.compile(stream_regexp)
        stream_obj_list = list()
        for port, stream_dict in list(self.port_stream_map.items()):
            for stream_name, stream_obj in list(stream_dict.items()):
                if r_obj.search(stream_name):
                    stream_obj_list.append(stream_obj)
        if len(stream_obj_list) == 0:
            BuiltIn().fail('''Failed to retrieve Stream Handle for one / more streams {} ..
            Please check the stream name!!'''.format(stream_regexp))
        return stream_obj_list

    def _get_pgid_from_stream(self, stream):
        return stream.get_pg_id()

    def verify_traffic(self, verify_parameters_list, streams_list=None, ports=None,
                       tolerance_list=None):
        """

        Args:
            verify_parameters:
            streams:
            ports:
            tolerance:

        Returns:

        """
        if not streams_list and not ports:
            BuiltIn().fail("Neither ports nor streams passed for collecting stats!!")
        pass_list = []
        fail_list = []
        if streams_list:
            streamsObj_list = list(itertools.chain.from_iterable(
                [self._get_stream_object(stream) for stream in streams_list]))
            logger.info("Stream obj list is {}".format(streamsObj_list))
            stream_to_pgid_map = dict()
            for stream in streamsObj_list:
                logger.info("Obj is {}".format(stream))
                stream_to_pgid_map[stream] = self._get_pgid_from_stream(stream)
            logger.info("Stream object list {0} {1}".format(
                streamsObj_list, stream_to_pgid_map))
            for i in range(len(streams_list)):
                retry = 4
                expected_val_list = []
                while retry > 0:
                    try:
                        logger.debug("Pg ids are {}".format(
                            list(stream_to_pgid_map.values())))
                        traffic_flow_stats = self.client.get_pgid_stats(
                            list(stream_to_pgid_map.values()))
                        traffic_flow_stats = traffic_flow_stats['flow_stats']
                        logger.info("All stats are {}".format(
                            traffic_flow_stats))
                        # self._append_verify_stats_dict(traffic_flow_stats)
                        logger.info("Traffic stats after modifying {}".format(
                            traffic_flow_stats))
                    except Exception as e:
                        logger.error("Failed with error ".format(e))

                    logger.info(
                        "Verifying stats for {}".format(streams_list[i]))
                    verify_parameters = verify_parameters_list[i]
                    verify_parameters = re.split(
                        r'\s+', verify_parameters.strip())
                    logger.info("Verify Parameters {0} : {1}".format(
                        verify_parameters[0], verify_parameters[1]))
                    traffic_stats_retrieved = traffic_flow_stats[stream_to_pgid_map[
                        streamsObj_list[i]]]
                    if verify_parameters[0] in self.verify_stream_stats_mapping['rx']:
                        expected_stats_info = self.verify_stream_stats_mapping[
                            'rx'][verify_parameters[0]]
                    else:
                        expected_stats_info = self.verify_stream_stats_mapping[
                            'tx'][verify_parameters[0]]
                    logger.info("Retrieved stats for {} is {}".format(
                        streams_list[i], traffic_stats_retrieved))
                    logger.info("Expected key is {}".format(
                        expected_stats_info))
                    expected_val = verify_parameters[1]
                    if expected_stats_info in ['rx_Bps', 'tx_Bps', 'tx_Kbps', 'tx_Mbps', 'rx_Kbps',
                                               'rx_Mbps', 'loss', 'loss_percent']:
                        additional_stats_dict = self._calculate_additional_stats(
                            traffic_stats_retrieved)
                        logger.info("additional stats dict :")
                        logger.info(additional_stats_dict)
                        current_value = additional_stats_dict[expected_stats_info]
                        logger.info("Current Value ".format(current_value))
                    else:
                        current_value = traffic_stats_retrieved[expected_stats_info]['total']
                    if verify_parameters[1] == "ZERO_DROP":
                        expected_val = traffic_stats_retrieved[self.verify_stream_stats_mapping[
                            'tx']['Tx_Frames']]['total']
                        current_value = traffic_stats_retrieved[self.verify_stream_stats_mapping[
                            'rx']['Rx_Frames']]['total']

                        logger.info("verify_parameters 1 : {}, 2 : {},".format(
                            verify_parameters[1], expected_val))
                    expected_val_list.append(current_value)
                    if self._check_tolerance(expected_val, current_value, tolerance_list[i]):
                        pass_list.append(streams_list[i])
                        break
                    else:
                        retry -= 1
                        if retry != 0:
                            time.sleep(5)
                            logger.info("Stats is {}".format(
                                traffic_flow_stats[stream_to_pgid_map[streamsObj_list[i]]]))
                        else:
                            self._dump_traffic_details(
                                self._get_stream_object(streams_list[i]))
                            sum = 0
                            avg = 0
                            for num in expected_val_list:
                                sum = sum + num
                            avg = sum / len(expected_val_list)

                            logger.info("Calculated  average {}  {}".format(
                                avg, expected_val_list))
                            if self._check_tolerance(expected_val, avg, 10):
                                pass_list.append(streams_list[i])
                                logger.info(
                                    "Traffic passed after avging out {}".format(streams_list[i]))
                            else:
                                fail_list.append(streams_list[i])
                                logger.info(
                                    "Traffic failed after avging out {}".format(streams_list[i]))

        if ports:
            ports = [self.port_name_to_id_map[port] for port in ports]
            traffic_stats = self.client.get_stats(ports=ports)
            for i in range(len(ports)):
                verify_parameters = verify_parameters_list[i]
                verify_parameters = re.split(r'\s+', verify_parameters.strip())
                logger.info("Verify Parameters {0} : {1}".format(
                    verify_parameters[0], verify_parameters[1]))
                retry = 4
                while retry > 0:
                    traffic_stats_retrieved = traffic_stats[ports[i]]
                    if verify_parameters[0] in self.verify_port_stats_mapping['rx']:
                        expected_stats = self.verify_port_stats_mapping['rx'][verify_parameters[0]]
                        logger.info("key in rx")
                    else:
                        expected_stats = self.verify_port_stats_mapping['tx'][verify_parameters[0]]
                        logger.info("key in tx")
                    if not expected_stats in traffic_stats_retrieved:
                        new_stats_dict = self._calculate_additional_port_stats(
                            traffic_stats_retrieved)
                        stats_retreived = new_stats_dict[expected_stats]
                    else:
                        stats_retreived = traffic_stats_retrieved[expected_stats]
                    if verify_parameters[1] == "ZERO_DROP":
                        verify_parameters[1] = traffic_stats_retrieved[
                            self.verify_port_stats_mapping['tx']['frames_tx']]
                        stats_retreived = traffic_stats_retrieved[
                            self.verify_port_stats_mapping['rx']['valid_frames_rx']]

                    if self._check_tolerance(verify_parameters[1], stats_retreived,
                                             tolerance_list[i]):
                        logger.info("Parameter: {0} matched. Expected: {1} Actual: {2}".format(
                            verify_parameters[0],
                            verify_parameters[1],
                            stats_retreived))
                        pass_list.append(ports[i])
                        break
                    else:
                        retry -= 1
                        if retry != 0:
                            logger.info(
                                '''Parameter: {0} did not Match. Expected: {1} Actual: {2},
                                 Retrying after 15 seconds...{3}/3
                                 '''.format(verify_parameters[0],
                                            verify_parameters[1],
                                            stats_retreived, 4 - retry))
                            time.sleep(15)
                            traffic_stats = self.client.get_stats(ports=ports)
                            logger.info("Stats is {}".format(traffic_stats))
                        else:
                            fail_list.append(port)
                            logger.error(
                                '''Parameter: {0} did not Match after 3 retries.
                                 Expected: {1} Actual: {2}'''.format(verify_parameters[0],
                                                                     verify_parameters[1],
                                                                     stats_retreived))
        if len(fail_list):
            raise Exception(
                '''Few streams/port did not Match the expected value
                  Failed - {0}  - Passed - {1}'''.format(fail_list, pass_list))

    def _calculate_additional_stats(self, traffic_stats_retrieved):
        new_stats_dict = dict()
        new_stats_dict['rx_Bps'] = old_div(
            traffic_stats_retrieved["rx_bps"]['total'], 8)
        new_stats_dict['tx_Bps'] = old_div(
            traffic_stats_retrieved["tx_bps"]['total'], 8)
        new_stats_dict['tx_Kbps'] = old_div(
            traffic_stats_retrieved["tx_bps"]['total'], 1000)
        new_stats_dict['tx_Mbps'] = old_div(traffic_stats_retrieved["tx_bps"]['total'],
                                            (1000 * 1000))
        new_stats_dict['rx_Kbps'] = old_div(
            traffic_stats_retrieved["rx_bps"]['total'], 1000)
        new_stats_dict['rx_Mbps'] = old_div(traffic_stats_retrieved["rx_bps"]['total'],
                                            (1000 * 1000))
        # new_stats_dict['rx_Mbps'] = old_div((traffic_stats_retrieved["rx_pps"]['total'] * 8 * 1368)  ,(1000*1000))
        new_stats_dict['loss'] = traffic_stats_retrieved["tx_pkts"]['total'] - \
            traffic_stats_retrieved["rx_pkts"]['total']
        new_stats_dict['loss_percent'] = (
            old_div(new_stats_dict['loss'],
                    traffic_stats_retrieved["tx_pkts"]['total'])) * 100
        return new_stats_dict

    def _calculate_additional_port_stats(self, traffic_stats_retrieved):
        new_stats_dict = dict()
        new_stats_dict['tx_rate_kbps'] = old_div(
            traffic_stats_retrieved['tx_bps'], 1024)
        new_stats_dict['tx_rate_mbps'] = old_div(traffic_stats_retrieved['tx_bps'],
                                                 (1024 * 1024))
        new_stats_dict['bytes_tx_rate'] = old_div(
            traffic_stats_retrieved['tx_bps'], 8)
        new_stats_dict['rx_rate_kbps'] = old_div(
            traffic_stats_retrieved['rx_bps'], 1024)
        new_stats_dict['rx_rate_mbps'] = old_div(traffic_stats_retrieved['rx_bps'],
                                                 (1024 * 1024))
        new_stats_dict['bytes_rx_rate'] = old_div(
            traffic_stats_retrieved['rx_bps'], 8)
        return new_stats_dict

    @staticmethod
    def _check_tolerance(expected_val, current_val, tolerance):
        """

        Args:
            expected_val:
            current_val:
            tolerance:

        Returns:

        """
        logger.debug("expected  value " + str(expected_val))
        logger.debug("current  value " + str(current_val))
        logger.debug("tolerance " + str(tolerance))
        if str(current_val) == 'N/A':
            raise Exception(
                "Error: Retrieved value from ixia is {}".format(current_val))
        try:
            low_bound = round(
                (float(expected_val) - (float(tolerance) / float(100) * float(expected_val))), 2)
            upper_bound = round(
                (float(expected_val) + (float(tolerance) / float(100) * float(expected_val))), 2)
            logger.debug(
                " {0} --- {1} --- {2} ".format(low_bound, expected_val, upper_bound))
            if round(float(current_val), 2) >= low_bound and round(float(
                    current_val), 2) <= upper_bound:
                return 1
            else:
                return 0
        except Exception as e:
            raise Exception(
                "Applying tolerance and verify failed due to error :{}".format(e))

