    def traffic_capture_and_replay(self, capture_interface, capture_filter, replay_interface, num_pkts_to_send, delay, pcap_filepath, dest_log_dir):
        logger.info("port mapping is :{}".format(self.port_name_to_id_map))
        logger.info("replay interface is :{}".format(replay_interface))
        port_no = self.port_name_to_id_map[replay_interface]
        logger.info("capture interface :{} and capture filter is :{}".format(capture_interface, capture_filter))
        if not capture_interface and not pcap_filepath:
            raise Exception("Mandatory argument not provided. Kindly provide either capture interface or pcap filepath...")
        if capture_interface:
            output_pcap= "result.pcap"
            self.traffic_start_capture(port_no, capture_type='data')
            time.sleep(int(delay))
            stats = self.client.get_stats()
            opackets = stats[port_no]['opackets']
            logger.info("{0} Output packets on port {1}\n".format(opackets, port_no))
            self.traffic_stop_and_extract(output_pcap, [port_no], dest_log_dir, capture_type='data')
            pcap_filepath = os.path.join(dest_log_dir, output_pcap)

            logger.info("Waiting for {} seconds".format(delay))
        self.client.push_pcap(pcap_filename = pcap_filepath, ports = port_no,count = num_pkts_to_send, force=True)
        self.client.wait_on_traffic(ports=[port_no])
        stats = self.client.get_stats()
        opackets = stats[port_no]['opackets']
        logger.info("{0} Output packets on port {1} after replay\n".format(opackets, port_no))

    def traffic_start_capture(self, port_no, capture_type, chassis_ip=None, card_no=None):
        """
        Args:
            chassis_ip:
            card_no:
            port_no:
            capture_type:
        Returns:
        """
        if port_no:
            port_no_list = [self.port_name_to_id_map[port_no]]
        else:
            port_no_list = self.client.get_acquired_ports()
        for port in port_no_list:
            # to be removed
            # self.client.reset(ports=port)
            ##
            logger.info("Setting port {0} to service mode.".format(port))
            self.client.set_service_mode(ports=port)
            if capture_type == "data":
                logger.info("Capturing on port {0} in {1} mode.".format(
                    port, capture_type))
                capture = self.client.start_capture(
                    rx_ports=port, limit=65535, mode='fixed', bpf_filter=None)
            if capture_type == "control":
                capture = self.client.start_capture(tx_ports=port, rx_ports=port, limit=65535,
                                                    mode='fixed',
                                                    bpf_filter=None)
            capture_port_id_dict[port] = int(capture['id'])

    def traffic_stop_and_extract(self, pcap_file_name, capture_port, dest_log_dir, capture_type):
        """

        Args:
            pcap_file_name:
            capture_port:
            capture_type:

        Returns:

      """
        logger.info("Destination directory is :{}".format(dest_log_dir))
        pcap_file_name_list = pcap_file_name.split(",")
        logger.info("Cap port is {}".format(capture_port))
        for port_no in capture_port:
            logger.info("FOR::Cap port is {}".format(port_no))
            logger.info("FOR::Cap port to capture id map is {}".format(capture_port_id_dict))
            logger.info(self.port_name_to_id_map)
            capture_id = capture_port_id_dict.get(port_no)
            logger.info("FOR::Cap id is {}".format(capture_id))
            pcap_file_name = pcap_file_name_list[capture_port.index(port_no)]
            dest_file = os.path.join(dest_log_dir, pcap_file_name)
            logger.info(
                "Stop the capture for port ***{0}*** with id ***{1}** and storing at ***{2}*** and type is {3}".format(
                    port_no, capture_id, dest_file, type(dest_file)))
            logger.debug(
                "File type after encode ***{}***".format(encode_str(dest_file)))
            self.client.stop_capture(capture_id, *encode_str(dest_file))

