    def traffic_enable_interface(self, interface_names):
        """

              Args:
                  interface_names:

              Returns:

        """
        if interface_names is None:
            interface_names = list(self.interface_map.keys())
        logger.info("Interface names: {}".format(interface_names))

        for interface in interface_names:
            if interface not in list(self.interface_map.keys()):
                BuiltIn().fail('''Enable interface failed as interface not found in traffic
                 generator config file...enter the correct interface''')
            else:
                try:
                    cmds = NSCmds()
                    all_nodes = self.client.set_namespace(
                        self.port_map[self.interface_map[interface]
                                      ['VportName']],
                        method='get_nodes')
                    logger.info("All nodes are :{}".format(all_nodes))

                    mac = self.get_mac()
                    logger.info("Mac is {}".format(mac))
                    cmds.add_node(mac)
                    if self.interface_map[interface].get('vlan') is not None:
                        cmds.set_vlan(
                            mac, [int(self.interface_map[interface]['vlan']['Vlans'])])
                    cmds.set_ipv4(mac, self.interface_map[interface]['ipv4']['IPv4address'],
                                  self.interface_map[interface]['ipv4']['IPv4Gateway'])
                    if self.interface_map[interface].get('ipv6') is not None:
                        logger.info("ipv6 is: {}".format(
                            self.interface_map[interface]['ipv6']['IPv6address']))
                        cmds.set_ipv6(mac, True,
                                      src_ipv6=self.interface_map[interface]['ipv6']['IPv6address'])
                    else:
                        cmds.set_ipv6(mac, True)
                    self.client.set_namespace_start(
                        self.port_map[self.interface_map[interface]['VportName']], cmds)
                    result = self.client.wait_for_async_results(
                        self.port_map[self.interface_map[interface]['VportName']])
                    all_nodes_after_enable = self.client.set_namespace(
                        self.port_map[self.interface_map[interface]
                                      ['VportName']],
                        method='get_nodes')
                    each_node_info = self.client.set_namespace(
                        self.port_map[self.interface_map[interface]
                                      ['VportName']],
                        method='get_nodes_info', macs_list=[mac])
                    logger.info("Nodes info for interface {} :{}".format(interface,
                                                                         each_node_info))
                    logger.info('''Nodes after enabling required node for interface {}
                     are:{}'''.format(interface, all_nodes_after_enable))

                    if mac in all_nodes_after_enable['result']['nodes']:
                        logger.info(
                            "Node {} enabled for interface {}".format(mac, interface))
                    else:
                        BuiltIn().fail("Enable interface failed")

                except Exception as e:
                    BuiltIn().fail("Enable interface failed due to :{}".format(e))

    def get_mac(self):
        mac = [0x00, 0x01, 0x02,
               random.randint(0x00, 0x7f),
               random.randint(0x00, 0xff),
               random.randint(0x00, 0xff)]

        auto_generated_mac = (':'.join(["%02x" % x for x in mac]))
        return auto_generated_mac

    def traffic_disable_interface(self, interface_names):
        """

              Args:
                  interface_names:

              Returns:

        """
        if interface_names is None:
            interface_names = list(self.interface_map.keys())
        logger.info("Interface names: {}".format(interface_names))

        for interface in interface_names:
            if interface not in list(self.interface_map.keys()):
                BuiltIn().fail('''Disable interface failed as interface not found in traffic
                 generator config file...enter the correct interface''')

            else:
                try:
                    cmds = NSCmds()
                    all_nodes = self.client.set_namespace(
                        self.port_map[self.interface_map[interface]
                                      ['VportName']],
                        method='get_nodes')
                    logger.info("All nodes are:{}".format(all_nodes))
                    for each_node in all_nodes['result']['nodes']:
                        each_node_info = self.client.set_namespace(
                            self.port_map[self.interface_map[interface]
                                          ['VportName']],
                            method='get_nodes_info', macs_list=[each_node])
                        ipv4_dict = dict()
                        ipv4_dict = each_node_info['result']['nodes'][0]['ipv4']
                        if self.interface_map[interface]['ipv4']['IPv4address'] == ipv4_dict['src'] \
                                and self.interface_map[interface]['ipv4']['IPv4Gateway'] \
                                == ipv4_dict['dst']:
                            try:
                                logger.info(
                                    "Node found and removing node {}".format(each_node))
                                remove_node = each_node
                                each_node = cmds.remove_node(each_node)
                            except Exception as e:
                                BuiltIn().fail("Remove node failed due to:".format(e))
                            self.client.set_namespace_start(self.port_map[self.interface_map[
                                interface]['VportName']], cmds)
                            result = self.client.wait_for_async_results(
                                self.port_map[self.interface_map[interface]['VportName']])
                            all_nodes_after_disable = self.client.set_namespace(
                                self.port_map[self.interface_map[interface]
                                              ['VportName']],
                                method='get_nodes')
                            # logger.info("Remove node result:{}".format(result))
                            logger.info('''Nodes after disabling required node for interface {}
                                are:{}'''.format(interface, all_nodes_after_disable))
                            if remove_node not in all_nodes_after_disable:
                                logger.info("Node {} disabled for interface {}".format(
                                    remove_node, interface))
                            else:
                                BuiltIn().fail("Disable interface failed")

                except Exception as e:
                    BuiltIn().fail("Disable interface failed due to :{}".format(e))

    def traffic_send_arp(self):
        """

        Returns:

        """
        logger.info("DEBUG:::***********interface::{} and port::{}".format(self.interface_map,
                                                                           self.port_map))
        interface_name = list(self.interface_map.keys())
        try:
            for interface in interface_name:

                logger.info("Acquired ports::{} and active ports ::{}".format(
                    self.client.get_acquired_ports(), self.client.get_active_ports()))
                self.client.set_port_attr(
                    ports=self.port_map[self.interface_map[interface]
                                        ['VportName']],
                    promiscuous=True)

                if self.interface_map[interface].get('vlan') is not None:
                    v_lan = int(self.interface_map[interface]['vlan']['Vlans'])

                else:
                    v_lan = None

                if v_lan is None:
                    self.client.clear_vlan(
                        ports=self.port_map[self.interface_map[interface]['VportName']])
                logger.info("vlan after clearing is:{}".format(v_lan))
                self.client.set_l3_mode(
                    port=self.port_map[self.interface_map[interface]
                                       ['VportName']],
                    src_ipv4=self.interface_map[interface]['ipv4']['IPv4address'],
                    dst_ipv4=self.interface_map[interface]['ipv4']['IPv4Gateway'],
                    vlan=v_lan)
                logger.info("port is :{}".format(
                    self.port_map[self.interface_map[interface]['VportName']]))
                self.client.resolve(ports=[self.port_map[self.interface_map[interface][
                    'VportName']]], retries=0, verbose=True, vlan=v_lan)
                logger.info(
                    "Arp request successful for interface {}".format(interface))

        except Exception as arp_error:
            BuiltIn().fail("Arp request failed due to:{} for interface {}".format(arp_error,
                                                                                  interface))

    def traffic_send_ping(self, interface_names, ns_ping=True):
        """

              Args:
                  interface_names:

              Returns:

              """
        result_list = list()
        if interface_names is None:
            interface_names = list(self.interface_map.keys())
        print(("interface name:", interface_names))
        if not ns_ping:
            for interface in interface_names:
                print(("interface_name_check", interface))
                print(("vlan:", self.interface_map[interface].get('vlan')))

                logger.info("Acquired ports::{} and active ports ::{}".format(
                    self.client.get_acquired_ports(),
                    self.client.get_active_ports()))
                if self.interface_map[interface].get('vlan') is not None:
                    v_lan = int(self.interface_map[interface]['vlan']['Vlans'])
                else:
                    v_lan = None
                if v_lan is None:
                    self.client.clear_vlan(
                        ports=self.port_map[self.interface_map[interface]['VportName']])
                logger.info("vlan after clearing is:{}".format(v_lan))
                self.client.set_l3_mode(port=self.port_map[self.interface_map[interface]['VportName']],
                                        src_ipv4=self.interface_map[interface]['ipv4']['IPv4address'],
                                        dst_ipv4=self.interface_map[interface]['ipv4']['IPv4Gateway'],
                                        vlan=v_lan)
                logger.info("L3 mode set successfully")
                port_attr = self.client.get_port_attr(
                    port=self.port_map[self.interface_map[interface]['VportName']])
                logger.info("Port attribute:{}".format(port_attr))

                return_value = self.client.ping_ip(
                    src_port=self.port_map[self.interface_map[interface]
                                           ['VportName']],
                    dst_ip=self.interface_map[interface]
                    ['ipv4']['IPv4Gateway'],
                    pkt_size=64, count=1, interval_sec=1)

                result_list.append(return_value)
                logger.info("Ping_return_list::{}".format(result_list))
                logger.info(
                    "return value::{}".format(
                        return_value[self.port_map[self.interface_map[interface]['VportName']]]))
                if return_value[self.port_map[self.interface_map[interface]['VportName']]].state == 2:
                    logger.info("ping successful")
                else:
                    BuiltIn().fail("Ping request failed for interface {}".format(interface))
        else:
            self._ns_ping_interfaces(interface_names)
        return result_list

    def _ns_ping_interfaces(self, interface_names):
        passed_interfaces = list()
        failed_interfaces = list()
        result_list = []
        ping_cmd_list = []
        status = 0
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh_client.get_host_keys().clear()
        ssh_client.set_missing_host_key_policy(
            paramiko.AutoAddPolicy())
        ssh_client.connect(self.traffic_gen_details.get('tcl_server_ip'),
                           port=22,
                           username=self.traffic_gen_details.get(
                               'tcl_username'),
                           password=self.traffic_gen_details.get(
                               'tcl_password'),
                           banner_timeout=60)

        for interface in interface_names:
            logger.debug("Interface is {}".format(interface))
            if interface not in list(self.interface_namespace_map.keys()):
                logger.debug(
                    "Please check this interface {}".format(interface))
                continue
            trex_ns = self.interface_namespace_map[interface]['linux-ns']
            if self.interface_namespace_map[interface].get('ipv4').get('dst') is not None:
                ping_cmd_list.append("ip netns exec {} ping {} -c 4".format(trex_ns,
                                                                            self.interface_namespace_map[interface][
                                                                                'ipv4']['dst']))
                cmd = "ip netns exec {} ping {} -c 4".format(trex_ns,
                                                             self.interface_namespace_map[interface]['ipv4']['dst'])
                logger.debug("Ping command  is {}".format(cmd))
            if self.interface_namespace_map[interface].get('ipv6').get('src') is not None:
                dst_ip = self.interface_map[interface]['ipv6']['IPv6Gateway']
                cmd = "ip netns exec {} ping6 {} -c 4".format(trex_ns, dst_ip)
                logger.debug("Ping command  is {}".format(cmd))
            try:
                stdin, stdout, stderr = ssh_client.exec_command(
                    cmd, timeout=60)
                output = stdout.read()
                logger.debug("Ping output is {}".format(output))
                status = stdout.channel.recv_exit_status()
                logger.debug("Ping status is {}".format(status))
            except Exception as e:
                logger.debug("Ping failed due to {}".format(e))
                status = 1
        ssh_client.close()

        # result_list = Communicator.get_instance().execute_commands_remotely_and_verify(
        #        ip=self.traffic_gen_details.get('tcl_server_ip'),
        #        username=self.traffic_gen_details.get('tcl_username'),
        #        password=self.traffic_gen_details.get('tcl_password'), commands=ping_cmd_list)
        logger.info("Ping results is {}".format(result_list))
        if not status:
            logger.info("Ping succeeded")
            # passed_interfaces.append(interface)
        else:
            logger.error("Ping failed for from ns ")
            # failed_interfaces.append(interface)
        if failed_interfaces:
            logger.error("Ping Failed for one/more interfaces Failed ::{} Passed :: {}".format(failed_interfaces,
                                                                                               passed_interfaces))
            # BuiltIn().fail("Ping request failed for one/more interfaces {}")
        else:
            return result_list

    def _get_packet_scapy_string(self, stream_object):
        for stream_obj in stream_object:
            code = stream_obj.to_code()
            result = re.findall(r'packet.*?\)\)', code, re.DOTALL)
            logger.debug("code is:{}".format(code))
            scapy_string = result[0]
            exec(compile(scapy_string, '<string>', 'exec'))
            logger.debug("packet length is:{}".format(len(packet)))
            return scapy_string, packet

    def traffic_change_size_onfly(self, streams, frame_size):
        try:
            stream_obj_list = self._get_stream_object(streams)
            scapy_string_output = self._get_packet_scapy_string(
                stream_obj_list)
            scapy_string = scapy_string_output[0]
            packet = scapy_string_output[1]
            logger.info("scapy string is:{} for stream: {}".format(
                scapy_string, streams))
            packet_length = len(packet)
            payload_size = len(packet[Raw])
            logger.info("payload size is:{}".format(payload_size))
            logger.info("frame size before updating:{}".format(packet_length))
            packet_size_without_payload = packet_length - len(packet[Raw])
            logger.info("packet size without payload:{}".format(
                packet_size_without_payload))
            new_payload_size = int(frame_size) - packet_size_without_payload
            logger.info("new payload size is:{}".format(new_payload_size))
            logger.info("packet obj :{}".format(packet[Raw].load))
            logger.info("packet obj len :{}".format(len(packet[Raw].load)))
            string_from_load = re.findall(r'(load.*)\*',
                                          scapy_string)[0].split("=")[1].replace("'", "").strip()
            logger.info("string from load is:{}".format(string_from_load))
            packet[Raw].load = string_from_load * new_payload_size
            logger.info("new packet obj :{}".format(packet[Raw].load))
            logger.info("new packet obj len :{}".format(len(packet[Raw].load)))
            new_payload_size = str(new_payload_size)
            # scapy string after execution is not updating the value of load
            exec(compile(scapy_string, '<string>', 'exec'))
            logger.info("scapy string after updating is:{} for stream: {}".format(scapy_string,
                                                                                  streams))
            new_packet_length = len(packet)
            logger.info("new packet length:{}".format(new_packet_length))
            logger.info("frame size is:{}".format(frame_size))
            if int(frame_size) == new_packet_length:
                logger.info("frame size after updating is:{}".format(
                    new_packet_length))
                logger.info("change size on fly successful with new frame size:{}".format(
                    new_packet_length))
            frame_size = str(frame_size)
        except Exception as change_frame_size_error:
            BuiltIn().fail("change frame size failed with the following exception {}".format(
                change_frame_size_error))

