    def traffic_change_rate(self, stream_names, frame_rate):
        """

                Args:
                    stream_names: name of the streams space seperated
                    frame_rate: frame rate

                Returns:

                """
        stream_obj_list = list()
        for stream in re.split(r"\s+", stream_names):
            logger.info(
                "**************Stream Name ::{} and object ::{}".format(
                    stream, self._get_stream_object(stream)))
            stream_obj_list += self._get_stream_object(stream)
        if not stream_obj_list:
            raise Exception("Empty Stream List, Please check the input")
        try:
            for stream in stream_obj_list:
                logger.debug(
                    'Stream object to be modified - {0}'.format(stream))
                logger.info("STREAM ID ::{}".format(stream.get_id()))
                port = self._get_port_for_stream(stream)
                logger.info("STREAM PORT ::{}".format(port))
                new_frame_rate = frame_rate + self.get_frame_rate(stream)
                self.client.update_streams(port=port, mult=new_frame_rate,
                                           stream_ids=[str(stream.get_pg_id())])
        except Exception as e:
            raise Exception("Failed due to {0}".format(e))

    def get_frame_rate(self, stream):
        t = stream.fields['mode']['rate']['type']
        if t == "pps":
            suffix = "pps"
        elif t == "bps_L1" or t == "bps_L2":
            suffix = "bps"
        elif t == "percentage":
            suffix = "%"
        return suffix
